<?php
declare(strict_types=1);require_once __DIR__.'/_helper.php';konsultasi_require_access($pdo);$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT k.*,s.nis,s.nisn,s.nama,mk.nama kelas,tp.nama tapel,g.nama petugas FROM konsultasi_bk k JOIN siswa s ON s.id=k.siswa_id JOIN tahun_pelajaran tp ON tp.id=k.tahun_pelajaran_id LEFT JOIN guru g ON g.id=k.petugas_id LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=k.tahun_pelajaran_id AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE k.id=? LIMIT 1");$st->execute([$id]);$r=$st->fetch();if(!$r){http_response_code(404);exit('Data konsultasi tidak ditemukan.');}$page_title='Detail Konsultasi';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main"><header class="topbar"><div class="topbar-title">Detail Konsultasi</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content konsultasi-module"><div class="page-header"><div><h1><i class="bi bi-chat-square-text-fill"></i> Detail Konsultasi</h1><p><?=e($r['tanggal'])?> · <?=e($r['tapel'])?></p></div><a class="btn btn-secondary" href="<?=BASE_URL?>konsultasi/index.php">Kembali</a></div><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Konsultasi berhasil disimpan.</div><?php endif;?><div class="dashboard-grid" style="grid-template-columns:repeat(2,minmax(0,1fr));gap:18px"><div class="dashboard-table-card"><h2><?=e($r['nama'])?></h2><p>NIS <?=e($r['nis'])?><?=!empty($r['nisn'])?' · NISN '.e($r['nisn']):''?> · Kelas <?=e($r['kelas']??'-')?></p><hr><p><strong>Jenis:</strong> <?=e(ucwords(str_replace('_',' ',$r['jenis'])))?></p><p><strong>Topik:</strong> <?=e($r['topik'])?></p><p><strong>Status:</strong> <?=e(ucfirst($r['status']))?></p><p><strong>Melibatkan orang tua:</strong> <?=$r['melibatkan_ortu']?'Ya':'Tidak'?></p><p><strong>Petugas:</strong> <?=e($r['petugas']??'-')?></p></div><div class="dashboard-table-card"><h3>Catatan Konsultasi</h3><p><strong>Permasalahan/Konteks</strong><br><?=nl2br(e($r['permasalahan']??'-'))?></p><p><strong>Hasil</strong><br><?=nl2br(e($r['hasil']??'-'))?></p><p><strong>Kesepakatan</strong><br><?=nl2br(e($r['kesepakatan']??'-'))?></p><p><strong>Tindak Lanjut</strong><br><?=nl2br(e($r['tindak_lanjut']??'-'))?></p></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
